  lc_tm A -> lc_tm (a_Abs psi0 A body) -> lc_tm (a_Var_f x) ->
  VTR (a_Abs psi0 A body) (a_Var_f x).
Proof.
  intros psi0 A body x HA HAbs Hx.
  eapply VTR_intro;
    try solve [exact HAbs];
    try solve [exact Hx];
    try solve [intros H; exfalso; inversion H];
    try solve [intros a' S; inversion S];
    try solve [intros b' S; inversion S];
    try solve [intros; congruence].
Qed.

Lemma VTR_Var_Abs : forall (psi0:grade) (A:tm) (body:tm) (x:atom),
  lc_tm A -> lc_tm (a_Abs psi0 A body) -> lc_tm (a_Var_f x) ->
  VTR (a_Var_f x) (a_Abs psi0 A body).
Proof.
  intros psi0 A body x HA HAbs Hx.
  eapply VTR_intro;
    try solve [exact HAbs];
    try solve [exact Hx];
    try solve [intros H; exfalso; inversion H];
    try solve [intros a' S; inversion S];
    try solve [intros b' S; inversion S];
    try solve [intros; congruence].
Qed.

'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
